WITH matched AS (SELECT a.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM orders a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.order_date BETWEEN pr.starts_on AND pr.ends_on) SELECT s.id, s.customer_id, s.store_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.promo_id, CASE WHEN channel RLIKE '^(partner|mobile)$' THEN 'CORE' ELSE 'EXTENDED' END AS channel_zone, (SELECT MAX(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS max_inventory_quantity FROM matched s ORDER BY max_inventory_quantity, channel;
